tape( 'the function performs the matrix-vector operation `y = alpha*A*x + beta*y` where `alpha` and `beta` are scalars, `x` and `y` are `n` element vectors, and `A` is an `n` by `n` banded symmetric matrix (row-major, lower)', function test( t ) {
	var expected;
	var out;
	var a;
	var x;
	var y;

	a = new Float64Array( rl.A );
	x = new Float64Array( rl.x );
	y = new Float64Array( rl.y );

	expected = new Float64Array( rl.y_out );

	out = dsbmv( rl.uplo, rl.N, rl.K, rl.alpha, a, rl.strideA1, rl.strideA2, rl.offsetA, x, rl.strideX, rl.offsetX, rl.beta, y, rl.strideY, rl.offsetY );
	t.strictEqual( out, y, 'returns expected value' );
	t.deepEqual( y, expected, 'returns expected value' );

	t.end();
});

