tape( 'if `N` is zero or the scalar constants are zero and unity, respectively, the function returns the second input vector unchanged (row-major)', function test( t ) {
	var expected;
	var out;
	var a;
	var x;
	var y;

	a = new Float64Array( rl.A );
	x = new Float64Array( rl.x );
	y = new Float64Array( rl.y );

	expected = new Float64Array( rl.y );

	out = dsbmv( rl.uplo, 0, rl.K, rl.alpha, a, rl.strideA1, rl.strideA2, rl.offsetA, x, rl.strideX, rl.offsetX, rl.beta, y, rl.strideY, rl.offsetY );
	t.strictEqual( out, y, 'returns expected value' );
	t.deepEqual( y, expected, 'returns expected value' );

	out = dsbmv( rl.uplo, rl.N, rl.K, 0.0, a, rl.strideA1, rl.strideA2, rl.offsetA, x, rl.strideX, rl.offsetX, 1.0, y, rl.strideY, rl.offsetY );
	t.strictEqual( out, y, 'returns expected value' );
	t.deepEqual( y, expected, 'returns expected value' );

	t.end();
});

